-- Catálogos por módulo (RRHH, compras, logística, contabilidad, ventas/POS).
-- Códigos DERIVADOS de los enums/valores reales del backend (no de los <option> hardcodeados,
-- que en varios casos estaban incompletos o desalineados). Convención V23/V24:
--   param_key = 'CATALOGO.<TABLA>.<CODIGO>'  ·  tenant_id NULL (global)  ·  tipo 'catalog'
-- Sirven al endpoint GET /users/api/system/parameters/catalog/{tabla} y a <app-catalog-select>.

ON CONFLICT (tenant_id, param_key) DO NOTHING;
